export const IR_INSTRUMENTS_COUNT = IR_INSTRUMENTS_QUESTIONS.length;

// The CPL Flight-Instruments (Part 1, A.7.x) bank is shared into the IR by
// mapping each IR section to the CPL aspect(s) that cover the same instrument,
// so Part 1 appears under the IR too (Part 2 questions already carry I.x ids).
const CPL_MAP: Record<string, string[]> = {
  "I.1": ["A.7.1"],   // air data instruments
  "I.2": ["A.7.2"],   // gyroscopic instruments (+ compasses)
  "I.4": ["A.7.3"],   // EFIS / flight director
  "I.6": ["A.7.6"],   // autopilot
  "I.8": ["A.7.8"],   // proximity & warning systems (GPWS/TCAS/altitude alert)
  "I.9": ["A.7.5"],   // air temperature indicators
  "I.10": ["A.7.7"],  // magnetism
};

export function getIRInstrumentsQuestionsBySection(sectionId: string): AirLawQuestion[] {
  const own = IR_INSTRUMENTS_QUESTIONS.filter((q) => q.sectionId === sectionId);
  const cpl = (CPL_MAP[sectionId] ?? []).flatMap((a) =>
    getInstrumentsQuestionsBySection(a)
  );
  return [...own, ...cpl];
}
